'use strict';
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {trophy:'<path d="M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v6M7 21h10"/>',message:'<path d="M21 11a8 8 0 0 1-8 8H7l-4 3V11a9 9 0 0 1 18 0Z"/><path d="M7 9h10M7 13h6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M9 21h6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',school:'<path d="m3 10 9-7 9 7v11H3zM9 21v-6h6v6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m4 12 5 5L20 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',sliders:'<path d="M3 6h18M3 12h18M3 18h18M7 3v6m10 0v6M9 15v6"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const categories = {city:'Городские',school:'Школьные',olympiad:'Олимпиады',project:'Проекты'};
const statuses = {draft:'Черновик',pending:'На проверке',published:'Опубликовано',rejected:'Отклонено',cancelled:'Отменено'};
const roles = {student:'Ученик',organizer:'Организатор',admin:'Администратор'};
const now = new Date();
const state = {me:null,cities:[],schools:[],topics:[],interests:[],favorites:[],plans:[],registrations:[],view:'feed',items:[],total:0,page:1,category:'',topic:'',city:'',school:'',search:'',sort:'recommended',filters:{},adminTab:'moderation',status:'',year:now.getFullYear(),month:now.getMonth(),calendarMode:'all',day:EventDates.dateKey(now)};
let requestNumber=0, viewController=null, detailNumber=0, confirmJob=null, searchTimer, modalKind='';
const canOrganize = () => ['admin','organizer'].includes(state.me?.role);
const cityName = id => state.cities.find(c=>c.id===Number(id))?.name || 'Город не выбран';
const schoolName = id => state.schools.find(s=>s.id===Number(id))?.name || 'Школа';
const isSaved = id => state.favorites.some(x=>x.event.id===Number(id));
const inPlan = id => state.plans.some(x=>x.event.id===Number(id));
const registration = id => state.registrations.find(x=>x.event_id===Number(id) && x.status==='registered');
const dt = value => new Date(value).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const dateRange = e => `${dt(e.starts_at)} — ${dt(e.ends_at)}`;
const money = e => Number(e.price) ? Number(e.price).toLocaleString('ru-RU')+' ₽' : 'Бесплатно';
const badge = e => `<span class="status-badge status-${e.status}">${statuses[e.status]||''}</span>`;
const gradeLabel = e => e.min_grade || e.max_grade ? `${e.min_grade||1}–${e.max_grade||11} классы` : 'Любой класс';
function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function showError(error,form){if(error.name==='AbortError'||error.status===401)return;const target=form?.querySelector('.form-error');if(target)target.textContent=error.message;else toast(error.message);}
function options(rows,value,empty='Не выбрано'){return `<option value="">${empty}</option>`+rows.map(r=>`<option value="${r.id}" ${String(r.id)===String(value)?'selected':''}>${esc(r.name)}${r.region?' — '+esc(r.region):''}</option>`).join('');}
function schoolOptions(city,value,empty='Все школы'){return options(state.schools.filter(s=>!city||s.city_id===Number(city)),value,empty);}
function geoFields(city,school,required=false,includeSchool=true){return `<label class="form-field">Населённый пункт<select name="city_id" data-form-city ${required?'required':''}>${options(state.cities,city,'Выбери населённый пункт')}</select><button type="button" class="location-link" data-geo-open="city"> Найти по всей России</button></label>${includeSchool?`<label class="form-field">Школа<select name="school_id" data-form-school>${schoolOptions(city,school,'Без школы')}</select><button type="button" class="location-link" data-geo-open="school"> Найти школу</button></label>`:''}`;}

function showAuth(mode='login',message=''){
  $('#application').hidden=true;$('#auth-screen').hidden=false;
  const signup=mode==='register';
  $('#auth-form-wrap').innerHTML=`<span class="auth-label">БУДЬ ВКУРСЕ</span><h2>${signup?'Начни свою историю':'С возвращением!'}</h2><p>${signup?'Создай аккаунт, чтобы находить события и сохранять свои планы.':'Войди, чтобы увидеть мероприятия и свой календарь.'}</p><form id="auth-form" data-mode="${mode}">${signup?'<label class="form-field">Тип аккаунта<select name="role" required><option value="student">Ученик</option><option value="organizer">Организатор</option></select><small>Ученик находит события и записывается. Организатор создаёт и публикует свои мероприятия.</small></label>':''}${signup?'<label class="form-field">Имя<input name="name" autocomplete="name" maxlength="80" required></label>':''}<label class="form-field">Email<input name="email" type="email" autocomplete="username" maxlength="254" required></label><label class="form-field">Пароль<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="${signup?8:1}" maxlength="128" required>${signup?'<small>Не менее 8 символов</small>':''}</label>${signup?'<label class="form-field">Повтори пароль<input name="confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label>':''}<div class="form-error" role="alert">${esc(message)}</div><button class="primary-button" type="submit">${signup?'Создать аккаунт':'Войти'} </button></form><div class="auth-switch">${signup?'Уже есть аккаунт?':'Первый раз здесь?'} <button data-auth-mode="${signup?'login':'register'}">${signup?'Войти':'Зарегистрироваться'}</button></div>${Api.hasSession()?'<button class="text-button" data-action="resume">Повторить подключение</button>':''}`;
}
function endSession(){window.Reminders?.stop();window.Activity?.reset();requestNumber++;detailNumber++;viewController?.abort();EventMap.stop();window.LocationSearch?.close();closeModal();state.me=null;state.items=[];state.favorites=[];state.plans=[];state.registrations=[];$('#events').innerHTML='';$('#modal-content').innerHTML='';$('#full-calendar').innerHTML='';$('#map-list').innerHTML='';$('#achievements-panel').innerHTML='';showAuth('login','Сессия завершена. Войди снова.');}
window.addEventListener('session-expired',endSession);
async function refreshPersonal(){const [favorites,plans,registrations,interests]=await Promise.all([Api.all('/me/favorites'),Api.all('/me/plans'),Api.all('/me/registrations'),Api.request('/me/interests')]);Object.assign(state,{favorites,plans,registrations,interests});}
async function refreshCatalogs(){const [cities,schools,topics]=await Promise.all([Api.request('/cities'),Api.all('/schools'),Api.request('/topics')]);Object.assign(state,{cities,schools,topics});}
async function initialize(){
  state.me=await Api.request('/me');
  await Promise.all([refreshPersonal(),refreshCatalogs()]);
  await window.MaxShell?.ready;
  $('#auth-screen').hidden=true;$('#application').hidden=false;
  const desired=location.hash.slice(1);state.view=['feed','map','saved','calendar','registrations','manage','admin','achievements','leaderboard','passport','teams','challenges','schoolboard','reminders'].includes(desired)?desired:'feed';
  if(state.view==='manage'&&!canOrganize()||state.view==='admin'&&state.me.role!=='admin')state.view='feed';
  await loadView();
  Reminders.start();
  window.dispatchEvent(new Event("app-session-ready"));
}
function filtersQuery(){const f={...state.filters,search:state.search,city_id:state.city,school_id:state.school,category:state.category,topic_id:state.topic,sort:state.sort};if(f.date){const [a,b]=EventDates.dayBounds(f.date);f.date_from=a.toISOString();f.date_to=b.toISOString();delete f.date;}return f;}
function clearFilters(){state.city='';state.school='';state.category='';state.topic='';state.search='';state.filters={};$('#search').value='';state.page=1;}
function renderChrome(){
  if(!state.me)return;
  $('#main').dataset.view=state.view;
  const meta={reminders:['Не пропусти главное.','Напоминания о событиях из твоего календаря.'],passport:['Твой паспорт активности','События, интересы и подтверждённые результаты.'],teams:['Сильнее вместе','Найди команду для следующего события.'],challenges:['Челленджи месяца','Попробуй новое и собери особые значки.'],schoolboard:['Рейтинг школ','Каждое участие помогает вашей школе.'],achievements:['Твои достижения','Каждое посещение — шаг к новой награде.'],leaderboard:['Те, кто действуют.','Рейтинг участников · реальные события и подтверждённые результаты'],feed:['Возможности вокруг тебя.','События, ради которых стоит выйти из дома.'],map:['Возможности — на карте','Перемещай карту: список обновится для видимой области.'],saved:['Твоё избранное','То, к чему хочется вернуться.'],calendar:['Календарь возможностей','События и личные планы по дням.'],registrations:['Мои записи','Мероприятия, на которые ты записался.'],manage:['Мои мероприятия','Создавай, публикуй и обновляй свои события.'],admin:['Управление','Все мероприятия и справочники. Неподходящие события можно удалить.']}[state.view];
  $('#page-title').textContent=meta[0];$('#page-subtitle').textContent=meta[1];
  $('#today-heading').textContent=new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();
  $('#profile-name').textContent=state.me.name;$('#avatar').textContent=state.me.name.slice(0,1).toUpperCase();$('#profile-class').textContent=state.me.role!=='organizer'&&state.me.grade?`${state.me.grade} класс`:roles[state.me.role];
  $('#workspace-school').textContent=state.me.role!=='organizer'&&state.me.school_id?schoolName(state.me.school_id):'Мой профиль';$('#workspace-city').textContent=state.me.city_id?cityName(state.me.city_id):'Выбери город в профиле';$('#city-current').textContent=state.me.city_id?cityName(state.me.city_id):'Мой город';$('#saved-count').textContent=state.favorites.length;
  document.querySelectorAll('[data-action="my-school"]').forEach(e=>e.hidden=state.me.role==='organizer');document.querySelectorAll('[data-organizer]').forEach(e=>e.hidden=!canOrganize());document.querySelectorAll('[data-admin]').forEach(e=>e.hidden=state.me.role!=='admin');
  document.querySelectorAll('[data-view]').forEach(e=>{e.classList.toggle('active',e.dataset.view===state.view);e.setAttribute('aria-current',e.dataset.view===state.view?'page':'false');});
  const browse=['feed','map','saved','calendar'].includes(state.view);
  $('#geo-toolbar').hidden=!browse;$('#browse-controls').hidden=!browse;$('#search').disabled=!browse;$('#sort-wrap').hidden=!['feed','saved'].includes(state.view);
  $('#geo-city').innerHTML=options(state.cities,state.city,'Все города');$('#geo-school').innerHTML=schoolOptions(state.city,state.school);
  $('#scope-caption').textContent=state.school?schoolName(state.school):state.city?cityName(state.city):'Все города и школы';
  $('.category-tabs').innerHTML=Object.entries({'':'Все события',...categories}).map(([id,name])=>`<button class="category ${state.category===id?'active':''}" data-category="${id}" aria-pressed="${state.category===id}">${name}</button>`).join('');
  $('#topic-chips').innerHTML=[{id:'',name:'Все интересы'},...state.topics].map(t=>`<button class="topic-chip ${String(t.id)===String(state.topic)?'active':''}" data-topic="${t.id}">${esc(t.name)}</button>`).join('');
  $('#active-filters').innerHTML=Object.keys(state.filters).length?'<button class="active-filter" data-action="clear-extra">Сбросить дополнительные фильтры ×</button>':'';
  $('#welcome-banner').hidden=state.view!=='feed'||!!state.search||!!state.city||!!state.school||!!state.category||!!state.topic||!!Object.keys(state.filters).length;
  document.querySelector('.display-switch').hidden=!['feed','saved','manage','registrations'].includes(state.view);
  $('#photo-explore').hidden=$('#welcome-banner').hidden;
  $('#editorial-discovery').hidden=$('#welcome-banner').hidden;
  $('#map-panel').hidden=state.view!=='map';$('#full-calendar').hidden=state.view!=='calendar';$('#events').hidden=['map','calendar','achievements','leaderboard',...Activity.views].includes(state.view);$('#achievements-panel').hidden=!['achievements','leaderboard',...Activity.views].includes(state.view);
  $('#view-tools').innerHTML=state.view==='manage'?`<div class="view-tools"><label class="form-field">Статус<select id="manage-status"><option value="">Все статусы</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${state.status===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary-button" data-action="create">${icon('plus')}Создать мероприятие</button></div>`:state.view==='admin'?`<div class="view-tools"><div class="category-tabs">${Object.entries({moderation:'Все мероприятия',cities:'Города',schools:'Школы',topics:'Темы'}).map(([k,v])=>`<button class="category ${state.adminTab===k?'active':''}" data-admin-tab="${k}">${v}</button>`).join('')}</div>${state.adminTab==='moderation'?`<label class="form-field">Статус<select id="manage-status"><option value="">Все статусы</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${state.status===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}${state.adminTab==='moderation'?`<label class="form-field">Статус<select id="manage-status"><option value="">Все статусы</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}" ${state.status===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}${state.adminTab!=='moderation'?`<button class="primary-button" data-catalog-new="${state.adminTab}">Добавить</button>`:''}</div>`:'';
  fillIcons();
}
function matchesFilters(e,f){return (!state.city||e.city_id===Number(state.city))&&(!state.school||e.school_id===Number(state.school))&&(!state.category||e.category===state.category)&&(!state.topic||e.topic_ids.includes(Number(state.topic)))&&(!state.search||`${e.title} ${cityName(e.city_id)} ${schoolName(e.school_id)}`.toLowerCase().includes(state.search.toLowerCase()))&&(!f.date||EventDates.occursOn(e,f.date))&&(!f.format||e.format===f.format)&&(!f.grade||(!e.min_grade||e.min_grade<=f.grade)&&(!e.max_grade||e.max_grade>=f.grade))&&(!f.age||(e.min_age==null||e.min_age<=f.age)&&(e.max_age==null||e.max_age>=f.age))&&(f.price_max==null||Number(e.price)<=Number(f.price_max))&&(f.price_min==null||Number(e.price)>=Number(f.price_min))&&(!f.place||`${e.place_name||''} ${e.address||''}`.toLowerCase().includes(f.place.toLowerCase()));}
function matches(e){return matchesFilters(e,state.filters);}
async function loadView(){
  if(!state.me)return;
  const sequence=++requestNumber;viewController?.abort();viewController=new AbortController();const signal=viewController.signal;
  renderChrome();$('#page-error').hidden=true;$('#pagination').innerHTML='';$('#results-count').textContent='Загружаем…';
  if(state.view==='map'){EventMap.show();return;}
  EventMap.pause();
  if(state.view==='calendar')$('#full-calendar').innerHTML='<div class="loading-state">Загружаем календарь…</div>';else $('#events').innerHTML='<div class="loading-state">Загружаем события…</div>';
  try{
    if(Activity.views.includes(state.view)){await Activity.show(signal);return;}
    if(['achievements','leaderboard'].includes(state.view)){await Achievements.show(signal);return;}
    let items=[],total=0;
    if(state.view==='feed') {const page=await Api.request('/events?'+Api.query({...filtersQuery(),page:state.page,limit:12}),{signal});items=page.items;total=page.total;}
    if(state.view==='saved'){items=state.favorites.map(x=>x.event).filter(matches);total=items.length;items.sort((a,b)=>new Date(state.sort==='deadline'?(a.registration_deadline||a.starts_at):a.starts_at)-new Date(state.sort==='deadline'?(b.registration_deadline||b.starts_at):b.starts_at));}
    if(state.view==='calendar'){const range=EventDates.monthBounds(state.year,state.month);items=state.calendarMode==='mine'?(await Api.all('/me/plans',range,signal)).map(x=>x.event).filter(matches):await Api.all('/events',{...filtersQuery(),...range},signal);total=items.length;}
    if(state.view==='registrations'){items=state.registrations.filter(r=>r.status==='registered'&&r.event).map(r=>r.event);total=items.length;}
    if(state.view==='manage'){const page=await Api.request('/me/events?'+Api.query({status:state.status,page:state.page,limit:12}),{signal});items=page.items;total=page.total;}
    if(state.view==='admin'&&state.adminTab==='moderation'){const page=await Api.request('/admin/events?'+Api.query({status:state.status,page:state.page,limit:12}),{signal});items=page.items;total=page.total;}
    if(state.view==='admin'&&state.adminTab!=='moderation'){items=state[state.adminTab];total=items.length;}
    if(sequence!==requestNumber||!state.me)return;
    state.items=items;state.total=total;
    $('#results-count').textContent=`Найдено: ${total}`;
    if(state.view==='calendar')EventCalendar.render(items);
    else if(state.view==='admin'&&state.adminTab!=='moderation')renderCatalog(items);
    else $('#events').innerHTML=items.length?items.map(card).join(''):emptyState();
    if(['feed','manage'].includes(state.view)||state.view==='admin'&&state.adminTab==='moderation')$('#pagination').innerHTML=total>12?`<button data-page="${state.page-1}" ${state.page===1?'disabled':''}> Назад</button><span>${state.page} / ${Math.ceil(total/12)}</span><button data-page="${state.page+1}" ${state.page*12>=total?'disabled':''}>Дальше </button>`:'';
    hydrateCovers();
  }catch(error){if(sequence!==requestNumber||error.name==='AbortError'||error.status===401)return;if(['achievements','leaderboard',...Activity.views].includes(state.view))$('#achievements-panel').innerHTML='<div class="empty-state">Не удалось загрузить раздел. Нажми «Обновить».</div>';$('#results-count').textContent='Не удалось загрузить';$('#page-error').hidden=false;$('#page-error').textContent=error.message;$('#events').innerHTML='<div class="empty-state"><h3>Попробуем ещё раз?</h3><button class="primary-button" data-action="refresh">Повторить</button></div>';if(state.view==='calendar')$('#full-calendar').innerHTML='<div class="empty-state"><p>Календарь не загружен. Нажми «Обновить».</p></div>';}
}
function emptyState(){
  if(state.view==='feed'){
    const filtered=state.city||state.school||state.category||state.topic||state.search||Object.values(state.filters).some(value=>value!==''&&value!=null&&value!==false);
    return `<div class="empty-state"><h3>${filtered?'По этим фильтрам событий пока нет':'Новые события скоро появятся здесь'}</h3><p>${filtered?'Попробуй другое направление или расширь поиск.':'Здесь будут опубликованные мероприятия организаторов. А пока выбери интересное направление ниже и познакомься с возможностями платформы.'}</p>${filtered?'<button class="secondary-button" data-action="reset">Сбросить фильтры</button>':'<button class="primary-button" data-action="organizer-intro">Предложить мероприятие</button>'}</div>`;
  }
  return `<div class="empty-state"><h3>${state.view==='saved'?'Здесь будет твоё избранное':state.view==='registrations'?'Ты пока не записался на события':state.view==='manage'?'Создай своё первое мероприятие':'Пока ничего не найдено'}</h3><p>${state.view==='manage'?'Сохрани черновик, затем опубликуй готовое мероприятие.':'Найди интересное событие в ленте и открой его карточку.'}</p>${state.view==='manage'?'<button class="primary-button" data-action="create">Создать мероприятие</button>':'<button class="secondary-button" data-view="feed">Найти мероприятие</button>'}</div>`;
}

function photo(e){const title=(e.title||'').toLowerCase();const pool={city:['nature.jpg','sport.jpg','art.jpg'],school:['science.jpg','team.jpg','art.jpg'],olympiad:['math.jpg','science.jpg'],project:['team.jpg','workshop.webp','science.jpg']}[e.category]||['team.jpg'];const themed=/спорт|баскет|футбол|турнир|бег/.test(title)?'sport.jpg':/рисов|искусств|творче|живопис/.test(title)?'art.jpg':/экол|природ|поход/.test(title)?'nature.jpg':null;const fallback=themed||pool[Math.abs(Number(e.id)||0)%pool.length];return `<img src="/assets/photos/${fallback}" ${e.cover_url?`data-cover="${esc(e.cover_url)}"`:''} alt="${esc(e.cover_url?e.title:'Иллюстрация: '+e.title)}" loading="lazy" decoding="async">`;}

function hydrateCovers(root=document){root.querySelectorAll('img[data-cover]').forEach(img=>{const path=img.dataset.cover;Api.cover(path).then(url=>{if(img.isConnected&&img.dataset.cover===path)img.src=url;}).catch(()=>{});});}
function card(e){const day=new Date(e.starts_at);return `<article class="event-card"><div class="poster photo-poster"><button class="image-open" data-event="${e.id}" aria-label="Открыть ${esc(e.title)}">${photo(e)}</button><span class="event-date-ticket"><b>${day.getDate()}</b><small>${esc(day.toLocaleDateString('ru-RU',{month:'short'}))}</small></span><span class="photo-topic">${categories[e.category]}</span><button class="save-button ${isSaved(e.id)?'saved':''}" data-save="${e.id}" aria-label="${isSaved(e.id)?'Убрать из избранного':'В избранное'}: ${esc(e.title)}" ${e.status!=='published'&&e.status!=='cancelled'?'hidden':''}>${icon('bookmark')}</button></div><div class="event-content"><div class="event-tags"><span class="event-tag">${e.format==='online'?'Онлайн':'Очно'}</span>${e.status!=='published'?badge(e):''}</div><div class="event-geography">${esc(cityName(e.city_id))}${e.school_id?' · '+esc(schoolName(e.school_id)):''}</div><h3><button class="event-title" data-event="${e.id}">${esc(e.title)}</button></h3><div class="event-meta">${icon('calendar')}<span>${dateRange(e)}</span></div><div class="event-meta">${icon('pin')}<span>${esc(e.place_name||(e.format==='online'?'Онлайн':'Площадка уточняется'))}</span></div><div class="event-bottom"><span>${gradeLabel(e)}</span><span class="event-price">${money(e)}</span></div>${state.view==='registrations'?`<div class="manage-actions"><button data-register="${e.id}" ${new Date(e.starts_at)<=new Date()?'disabled':''}>${registration(e.id)?.attended?'Посещение подтверждено':new Date(e.starts_at)<=new Date()?'Ты записан':'Отменить мою запись'}</button></div>`:''}${['manage','admin'].includes(state.view)?`<div class="manage-actions"><button data-event="${e.id}">Управлять</button>${e.status!=='cancelled'?`<button data-edit="${e.id}">Редактировать</button>`:''}</div>`:''}</div></article>`;}
function openModal(html,kind=''){window.Activity?.stop();detailNumber++;modalKind=kind;EventMap.closePicker();$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;$('#modal-content').scrollTop=0;fillIcons($('#modal'));hydrateCovers($('#modal'));}
function closeModal(){window.Activity?.stop();detailNumber++;EventMap.closePicker();$('#modal').close();modalKind='';}
function detail(label,value){return `<div class="detail-item"><div><small>${esc(label)}</small><b>${esc(value)}</b></div></div>`;}
async function openEvent(id){
  openModal('<div class="loading-state">Загружаем мероприятие…</div>','detail');const sequence=detailNumber;
  try{const e=await Api.request('/events/'+id);if(sequence!==detailNumber)return;
    const owner=e.organizer_id===state.me.id||state.me.role==='admin';
    const reg=registration(id);const closed=e.status!=='published'||new Date(e.starts_at)<=new Date()||e.registration_deadline&&new Date(e.registration_deadline)<=new Date();
    let entry=e.registration_mode==='internal'?`<button class="primary-button" data-register="${e.id}" ${closed?'disabled':''}>${reg?(reg.attended?'Посещение подтверждено':closed?'Ты записан':'Отменить мою запись'):closed?'Запись закрыта':'Записаться'}</button>`:e.registration_mode==='external'&&e.registration_url&&!closed?`<a class="primary-button" href="${esc(e.registration_url)}" target="_blank" rel="noopener noreferrer">Записаться у организатора </a>`:'<span class="mini-label">'+(e.registration_mode==='none'?'Без предварительной записи':'Запись закрыта')+'</span>';
    let management='';
    if(owner&&canOrganize())management=`<div class="manage-actions">${e.status!=='cancelled'?`<button data-edit="${e.id}">Редактировать</button>`:''}${['draft','pending','rejected'].includes(e.status)?`<button data-transition="publish" data-id="${e.id}">Опубликовать</button>`:''}${e.status==='published'?`<button class="danger" data-transition="cancel" data-id="${e.id}">Отменить мероприятие</button>`:''}${e.status==='draft'||state.me.role==='admin'?`<button class="danger" data-delete-event="${e.id}">${e.status==='draft'?'Удалить черновик':'Удалить мероприятие'}</button>`:''}<button data-participants="${e.id}">Участники</button></div>`;
    $('#modal-content').innerHTML=`<div class="poster photo-poster modal-poster">${photo(e)}</div><div class="modal-kicker">${categories[e.category]} · ${e.format==='online'?'Онлайн':'Очно'} ${badge(e)}</div><h2 class="modal-heading">${esc(e.title)}</h2><div class="detail-grid">${detail('Когда',dateRange(e))}${detail('Где',cityName(e.city_id)+' · '+(e.place_name||'Онлайн'))}${e.address?detail('Адрес',e.address):''}${e.school_id?detail('Школа',schoolName(e.school_id)):''}${detail('Для кого',gradeLabel(e))}${detail('Стоимость',money(e))}${e.registration_deadline?detail('Запись до',dt(e.registration_deadline)):''}${e.capacity?detail('Всего мест',e.capacity):''}</div><p class="modal-description">${esc(e.description)}</p>${e.take_with_you?`<b>Что взять с собой</b><p class="modal-description">${esc(e.take_with_you)}</p>`:''}${e.format==='offline'&&e.latitude!=null?`<button class="secondary-button" data-show-map="${e.id}" data-lat="${e.latitude}" data-lng="${e.longitude}">Показать на карте</button>`:''}${e.status==='published'||inPlan(e.id)?`<button class="secondary-button" data-show-calendar="${esc(e.starts_at)}" data-calendar-target="${e.status==='published'?'all':'mine'}">Показать в календаре</button>`:''}${e.online_url?`<p><a href="${esc(e.online_url)}" target="_blank" rel="noopener noreferrer">Перейти на онлайн-площадку </a></p>`:''}${['published','cancelled'].includes(e.status)?`<div class="detail-actions">${entry}<button class="secondary-button" data-plan="${e.id}">${inPlan(id)?'Убрать из планов':'Добавить в планы'}</button><button class="secondary-button" data-save="${e.id}" data-detail="true">${isSaved(id)?'Убрать из избранного':'В избранное'}</button></div>`:''}${reg?`<p class="form-hint">Ты записан на это мероприятие. Время напоминания можно изменить ниже.</p>${e.organizer_max_url?`<p><a class="secondary-button" href="${esc(e.organizer_max_url)}" target="_blank" rel="noopener noreferrer">Написать организатору в MAX </a></p>`:'<p class="form-hint">Организатор пока не указал контакт MAX.</p>'}`:''}${e.status==='published'&&new Date(e.ends_at)>new Date()?`<button class="secondary-button" data-reminder-settings="${e.id}">Настроить напоминание</button>`:''}${Activity.eventActions(e,reg,owner)}${management}`;hydrateCovers($('#modal'));
  }catch(error){if(sequence!==detailNumber)return;$('#modal-content').innerHTML=`<h2>Мероприятие недоступно</h2><p>${esc(error.message)}</p>`;}
}
async function afterMutation(id){await refreshPersonal();await loadView();Reminders.refresh();if(id&&$('#modal').open&&modalKind==='detail')await openEvent(id);}
function confirmAction(title,text,job){confirmJob=job;openModal(`<h2 class="modal-heading">${esc(title)}</h2><p class="modal-description">${esc(text)}</p><div class="form-actions"><button class="secondary-button" data-action="close">Назад</button><button class="primary-button" data-action="confirm">Подтвердить</button></div>`,'confirm');}
function profileForm(){const u=state.me;const learner=u.role!=='organizer';openModal(`<div class="modal-kicker">${roles[u.role]}</div><h2 class="modal-heading">Твой профиль</h2><p class="modal-description">${esc(u.email)}</p><form id="profile-form"><div class="form-grid"><label class="form-field">Имя<input name="name" value="${esc(u.name)}" maxlength="80" required></label>${learner?`<label class="form-field">Класс<select name="grade"><option value="">Не указан</option>${Array.from({length:11},(_,i)=>`<option value="${i+1}" ${u.grade===i+1?'selected':''}>${i+1} класс</option>`).join('')}</select></label>`:''}${geoFields(u.city_id,u.school_id,false,learner)}${canOrganize()?`<label class="form-field full">Твой контакт MAX (необязательно)<input name="max_contact_url" value="${esc(u.max_contact_url||'')}" maxlength="240" placeholder="@username или https://max.ru/u/…"><small>Участник увидит кнопку «Написать организатору» после регистрации на событие. Скопируй свою ссылку из профиля MAX.</small></label>`:''}</div><div class="form-error" role="alert"></div><div class="form-actions"><button class="primary-button" type="submit">Сохранить профиль</button></div></form><div class="profile-tools"><button class="secondary-button" data-max-connection="open">Напоминания в MAX</button><button class="secondary-button" data-view="passport">Паспорт активности</button><button class="secondary-button" data-view="teams">Найти команду</button><button class="secondary-button" data-view="challenges">Челленджи месяца</button><button class="secondary-button" data-view="schoolboard">Рейтинг школ</button><button class="secondary-button" data-view="achievements">Мои достижения</button><button class="secondary-button" data-view="leaderboard">Общий рейтинг</button><button class="secondary-button" data-view="saved">Избранное</button><button class="secondary-button" data-view="registrations">Мои записи</button>${canOrganize()?'<button class="secondary-button" data-view="manage">Мои мероприятия</button>':''}${u.role==='admin'?'<button class="secondary-button" data-view="admin">Управление</button>':''}<button class="secondary-button" data-action="logout">Выйти</button><button class="text-button danger" data-action="deactivate">Деактивировать аккаунт</button></div>`,'profile');}
function interestsForm(){openModal(`<h2 class="modal-heading">Что тебе интересно?</h2><p class="modal-description">Эти темы помогут подобрать события в ленте.</p><form id="interests-form"><div class="interest-grid">${state.topics.map(t=>`<label class="interest-option"><input type="checkbox" name="topic" value="${t.id}" ${state.interests.some(x=>x.id===t.id)?'checked':''}>${esc(t.name)}</label>`).join('')||'<p>Темы пока не добавлены.</p>'}</div><div class="form-error" role="alert"></div><div class="form-actions"><button class="primary-button" type="submit">Сохранить интересы</button></div></form>`);}
function filtersForm(){const f=state.filters;openModal(`<h2 class="modal-heading">Найдём подходящее</h2><form id="filters-form"><div class="form-grid"><label class="form-field">Дата<input type="date" name="date" value="${esc(f.date||'')}"></label><label class="form-field">Формат<select name="format"><option value="">Любой</option><option value="offline" ${f.format==='offline'?'selected':''}>Очно</option><option value="online" ${f.format==='online'?'selected':''}>Онлайн</option></select></label><label class="form-field">Класс<input name="grade" type="number" min="1" max="11" value="${f.grade||''}"></label><label class="form-field">Возраст<input name="age" type="number" min="0" max="120" value="${f.age??''}"></label><label class="form-field">Цена от, ₽<input name="price_min" type="number" min="0" step="0.01" value="${f.price_min??''}"></label><label class="form-field">Цена до, ₽<input name="price_max" type="number" min="0" step="0.01" value="${f.price_max??''}" placeholder="0 — бесплатно"></label><label class="form-field full">Площадка или адрес<input name="place" value="${esc(f.place||'')}" maxlength="200"></label></div><div class="form-error" role="alert"></div><div class="form-actions"><button class="primary-button" type="submit">Применить</button></div></form>`);}
function input(name,label,value='',type='text',attrs=''){return `<label class="form-field">${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;}
async function eventForm(id){
  if(!canOrganize())return;
  const e=id?await Api.request('/events/'+id):{};const start=new Date(Date.now()+86400000);start.setHours(15,0,0,0);const end=new Date(start.getTime()+2*3600000);
  openModal(`<div class="modal-kicker">${id?'РЕДАКТИРОВАНИЕ':'НОВОЕ МЕРОПРИЯТИЕ'}</div><h2 class="modal-heading">${id?'Обновить событие':'Дай идее аудиторию'}</h2><p class="form-hint">Сохрани черновик, затем нажми «Опубликовать». Изменения опубликованного события видны сразу. Время в форме — по часовому поясу устройства.</p><form id="event-form" data-id="${id||''}" data-cover-id="${e.cover_file_id||''}"><div class="form-grid"><label class="form-field full">Название<input name="title" maxlength="150" minlength="3" required value="${esc(e.title||'')}"></label><label class="form-field">Раздел<select name="category">${Object.entries(categories).map(([k,v])=>`<option value="${k}" ${e.category===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="form-field">Формат<select name="format" data-format><option value="offline" ${e.format!=='online'?'selected':''}>Очно</option><option value="online" ${e.format==='online'?'selected':''}>Онлайн</option></select></label>${geoFields(e.city_id||state.me.city_id||state.city,e.school_id,true)}${input('starts_at','Начало',EventDates.localInput(e.starts_at||start),'datetime-local','required')}${input('ends_at','Окончание',EventDates.localInput(e.ends_at||end),'datetime-local','required')}<label class="form-field full">Описание<textarea name="description" minlength="10" maxlength="10000" required>${esc(e.description||'')}</textarea></label><label class="form-field full">Обложка<input name="cover" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG или WEBP, до 5 МиБ</small></label>${e.cover_file_id?'<label class="form-field full"><span class="check-line"><input name="remove_cover" type="checkbox">Убрать текущую обложку</span></label>':''}<h3 class="form-section-title">Место проведения</h3><div class="full" id="offline-fields"><div class="form-grid">${input('place_name','Площадка',e.place_name,'text','maxlength="200"')}${input('address','Адрес',e.address,'text','maxlength="1000"')}</div><p class="form-hint">Выбери точку на карте или введи координаты. Для публикации очного события нужны и адрес, и точка.</p><div class="picker-tools"><button type="button" class="secondary-button" data-geo-open="place"> Найти адрес</button><button type="button" class="secondary-button" data-action="picker-locate"> Моё местоположение</button><button type="button" class="secondary-button" data-action="picker-expand"> Увеличить карту</button></div><div id="place-map" class="editor-map"></div><p class="form-hint" id="picker-point-status">Нажми на карту, чтобы поставить точку. Метку можно перетаскивать.</p><div class="form-grid">${input('latitude','Широта',e.latitude,'number','min="-85.0511" max="85.0511" step="any" data-coordinate')}${input('longitude','Долгота',e.longitude,'number','min="-180" max="180" step="any" data-coordinate')}</div></div><div class="full" id="online-fields">${input('online_url','Ссылка на онлайн-площадку',e.online_url,'url')}</div><h3 class="form-section-title">Участие</h3><label class="form-field">Способ записи<select name="registration_mode" data-registration-mode>${Object.entries({none:'Без регистрации на событие',internal:'Запись на этом сайте',external:'На сайте организатора'}).map(([k,v])=>`<option value="${k}" ${e.registration_mode===k?'selected':''}>${v}</option>`).join('')}</select></label>${input('capacity','Количество мест',e.capacity,'number','min="1"')}<div class="full" id="external-fields">${input('registration_url','Ссылка для записи',e.registration_url,'url')}</div>${input('registration_deadline','Запись до',EventDates.localInput(e.registration_deadline),'datetime-local')}${input('price','Цена, ₽',e.price||'0.00','number','min="0" max="99999999.99" step="0.01" required')}${input('min_grade','С какого класса',e.min_grade,'number','min="1" max="11"')}${input('max_grade','По какой класс',e.max_grade,'number','min="1" max="11"')}${input('min_age','Возраст от',e.min_age,'number','min="0" max="120"')}${input('max_age','Возраст до',e.max_age,'number','min="0" max="120"')}<label class="form-field full">Что взять с собой<textarea name="take_with_you" maxlength="2000">${esc(e.take_with_you||'')}</textarea></label><h3 class="form-section-title">Темы</h3><div class="interest-grid full">${state.topics.map(t=>`<label class="interest-option"><input type="checkbox" name="topic" value="${t.id}" ${(e.topic_ids||[]).includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')}</div></div><div class="form-error" role="alert"></div><div class="form-actions"><button class="secondary-button" type="button" data-action="close">Отмена</button><button class="primary-button" type="submit">${id?'Сохранить изменения':'Сохранить черновик'}</button></div></form>`,'editor');
  updateEditorFields();EventMap.openPicker(e);
}
function updateEditorFields(){const form=$('#event-form');if(!form)return;const online=form.elements.format.value==='online';$('#offline-fields').hidden=online;$('#online-fields').hidden=!online;$('#external-fields').hidden=form.elements.registration_mode.value!=='external';if(!online)EventMap.resizePicker();}
async function saveEvent(form){
  const fd=new FormData(form);const num=k=>fd.get(k)===''?null:Number(fd.get(k));const text=k=>String(fd.get(k)||'').trim()||null;
  const starts=new Date(fd.get('starts_at')),ends=new Date(fd.get('ends_at'));
  if(ends<=starts)throw new Error('Окончание должно быть позже начала.');
  const deadline=text('registration_deadline');if(deadline&&new Date(deadline)>starts)throw new Error('Запись должна закончиться не позже начала.');
  const online=fd.get('format')==='online';if(!online&&((num('latitude')===null)!==(num('longitude')===null)))throw new Error('Укажи обе координаты или оставь обе пустыми.');
  let cover=fd.has('remove_cover')?null:(Number(form.dataset.coverId)||null);const file=fd.get('cover');
  if(file?.size){if(file.size>5*1024*1024)throw new Error('Обложка должна быть не больше 5 МиБ.');const upload=new FormData();upload.set('file',file);const result=await Api.request('/files',{method:'POST',body:upload});cover=result.id;form.dataset.coverId=String(cover);form.elements.cover.value='';}
  const body={title:text('title'),description:text('description'),category:fd.get('category'),city_id:num('city_id'),school_id:num('school_id'),cover_file_id:cover,topic_ids:fd.getAll('topic').map(Number),starts_at:starts.toISOString(),ends_at:ends.toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,registration_deadline:deadline?new Date(deadline).toISOString():null,format:fd.get('format'),place_name:online?null:text('place_name'),address:online?null:text('address'),latitude:online?null:num('latitude'),longitude:online?null:num('longitude'),online_url:online?text('online_url'):null,min_grade:num('min_grade'),max_grade:num('max_grade'),min_age:num('min_age'),max_age:num('max_age'),price:String(fd.get('price')),capacity:num('capacity'),registration_mode:fd.get('registration_mode'),registration_url:fd.get('registration_mode')==='external'?text('registration_url'):null,take_with_you:text('take_with_you')};
  const id=form.dataset.id;const result=await Api.request('/events'+(id?'/'+id:''),{method:id?'PATCH':'POST',body});
  closeModal();await afterMutation();await openEvent(result.id);toast(result.status==='published'?'Изменения опубликованы':'Черновик сохранён');
}
function renderCatalog(items){$('#events').innerHTML=items.length?`<div class="catalog-list">${items.map(x=>`<article class="catalog-row"><div><b>${esc(x.name)}</b><p>${esc(x.address||x.region||x.slug||'')}</p></div><div><button class="secondary-button" data-catalog-edit="${state.adminTab}" data-id="${x.id}">Изменить</button><button class="secondary-button danger" data-catalog-delete="${state.adminTab}" data-id="${x.id}">${state.adminTab==='schools'?'Деактивировать':'Удалить'}</button></div></article>`).join('')}</div>`:'<div class="empty-state"><h3>Пока пусто</h3><p>Добавь первую запись в справочник.</p></div>';}
function catalogForm(kind,id){const row=state[kind].find(x=>x.id===Number(id))||{};let fields=input('name','Название',row.name,'text','required maxlength="100"');if(kind==='cities')fields+=input('region','Регион',row.region,'text','required maxlength="120"')+input('country_code','Код страны (две буквы)',row.country_code||'RU','text','required pattern="[A-Z]{2}" maxlength="2"')+input('latitude','Широта',row.latitude,'number','required min="-90" max="90" step="any"')+input('longitude','Долгота',row.longitude,'number','required min="-180" max="180" step="any"');if(kind==='schools')fields+=`<label class="form-field">Город<select name="city_id" required>${options(state.cities,row.city_id,'Выбери город')}</select></label>`+input('address','Адрес',row.address,'text','required')+input('latitude','Широта (необязательно)',row.latitude,'number','min="-90" max="90" step="any"')+input('longitude','Долгота (необязательно)',row.longitude,'number','min="-180" max="180" step="any"');if(kind==='topics')fields+=input('slug','Короткий код латиницей',row.slug,'text','required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxlength="100"');openModal(`<h2 class="modal-heading">${id?'Изменить запись':'Добавить запись'}</h2><form id="catalog-form" data-kind="${kind}" data-id="${id||''}"><div class="form-grid">${fields}</div><div class="form-error" role="alert"></div><div class="form-actions"><button class="primary-button" type="submit">Сохранить</button></div></form>`);}
async function navigate(view){if(view==='manage'&&!canOrganize()||view==='admin'&&state.me?.role!=='admin')return;closeModal();const changed=state.view!==view;if(changed)state.status='';state.view=view;state.page=1;history.pushState(null,'','#'+view);if(changed)window.scrollTo({top:0,left:0,behavior:'instant'});await loadView();}
async function handleClick(button){
  const d=button.dataset;
  if(d.authMode){showAuth(d.authMode);return;}
  if(d.action==='resume'){await initialize();return;}
  if(!state.me)return;
  if(['community','hub','passportUser','schoolOrder','ticket','scanner','scanCamera','certificate','teamCreate','teamEdit','teamJoin','teamMember','teamLeave','teamDelete','reviewDelete'].some(key=>key in d)){await Activity.handleClick(d);return;}
  if(d.maxDownload){await MaxShell.download(d.maxDownload,d.filename);return;}
  if(d.reminderSettings){Reminders.settings(d.reminderSettings);return;}
  if(d.reminderRead){await Reminders.read(d.reminderRead);return;}
  if(d.action==='organizer-intro'){if(canOrganize())await eventForm();else openModal('<h2>Создавай события.</h2><p>Публикация доступна аккаунту организатора. Выйди из текущего аккаунта и при регистрации выбери роль «Организатор».</p><button class="primary-button" data-action="logout">Выйти и зарегистрироваться</button>');return;}
  if(d.achievementUser||d.attendance){await Achievements.handleClick(d);return;}
  if(d.view){await navigate(d.view);return;}
  if('category' in d){state.category=d.category;state.page=1;await loadView();return;}
  if('topic' in d){state.topic=d.topic;state.page=1;await loadView();return;}
  if(d.page){state.page=Number(d.page);await loadView();return;}
  if(d.event){await openEvent(d.event);return;}
  if(d.edit){await eventForm(d.edit);return;}
  if(d.save){await Api.request('/me/favorites/'+d.save,{method:isSaved(d.save)?'DELETE':'PUT'});await afterMutation(d.detail?d.save:null);toast('Избранное обновлено');return;}
  if(d.plan){await Api.request('/me/plans/'+d.plan,{method:inPlan(d.plan)?'DELETE':'PUT',body:inPlan(d.plan)?undefined:{}});await afterMutation(d.plan);toast('Планы обновлены');return;}
  if(d.register){const cancel=!!registration(d.register);await Api.request('/events/'+d.register+'/registrations'+(cancel?'/me':''),{method:cancel?'DELETE':'POST'});await afterMutation(d.register);toast(cancel?'Запись отменена':'Ты записан на мероприятие');return;}
  if(d.transition){const run=async()=>{await Api.request(`/events/${d.id}/${d.transition}`,{method:'POST'});closeModal();await afterMutation();await openEvent(d.id);};if(d.transition==='cancel')confirmAction('Отменить мероприятие?','Оно исчезнет из ленты, но участники увидят статус отмены.',run);else await run();return;}
  if(d.deleteEvent){confirmAction('Удалить мероприятие?',state.me.role==='admin'?'Событие, записи участников, избранное и планы на него будут удалены. Это действие нельзя отменить.':'Черновик будет удалён. Это действие нельзя отменить.',async()=>{await Api.request('/events/'+d.deleteEvent,{method:'DELETE'});closeModal();await afterMutation();toast('Мероприятие удалено');});return;}
  if(d.reject){openModal(`<h2>Почему событие отклонено?</h2><form id="reject-form" data-id="${d.reject}"><label class="form-field">Комментарий<textarea name="comment" minlength="3" maxlength="2000" required></textarea></label><div class="form-error" role="alert"></div><div class="form-actions"><button class="primary-button">Отклонить</button></div></form>`);return;}
  if(d.participants){await Achievements.participants(d.participants);return;}
  if(d.history){const rows=await Api.request(`/events/${d.history}/moderation`);openModal(`<h2>История проверки</h2>${rows.map(x=>`<div class="catalog-row"><div><b>${x.decision==='approved'?'Одобрено':'Отклонено'}</b><p>${esc(x.comment||'Без комментария')}</p></div><small>${dt(x.created_at)}</small></div>`).join('')||'<p>Решений ещё нет.</p>'}`);return;}
  if(d.showCalendar){clearFilters();Object.assign(state,EventDates.calendarPosition(d.showCalendar));state.calendarMode=d.calendarTarget;await navigate('calendar');return;}
  if(d.showMap){clearFilters();await navigate('map');EventMap.focus(Number(d.lat),Number(d.lng));return;}
  if(d.mapFocus){EventMap.select(Number(d.mapFocus));return;}
  if(d.calendarMonth){const date=new Date(state.year,state.month+Number(d.calendarMonth),1);state.year=date.getFullYear();state.month=date.getMonth();state.day=EventDates.dateKey(date);await loadView();return;}
  if(d.calendarDay){state.day=d.calendarDay;EventCalendar.render(state.items);hydrateCovers();return;}
  if(d.calendarMode){state.calendarMode=d.calendarMode;await loadView();return;}
  if(d.adminTab){state.adminTab=d.adminTab;state.page=1;await refreshCatalogs();await loadView();return;}
  if(d.catalogNew){catalogForm(d.catalogNew);return;}
  if(d.catalogEdit){catalogForm(d.catalogEdit,d.id);return;}
  if(d.catalogDelete){confirmAction(d.catalogDelete==='schools'?'Деактивировать школу?':'Удалить запись?','Если запись используется, сервер сообщит об этом и сохранит данные.',async()=>{await Api.request(`/${d.catalogDelete}/${d.id}`,{method:'DELETE'});await refreshCatalogs();closeModal();await loadView();});return;}
  switch(d.action){
    case 'close':closeModal();break;
    case 'confirm':if(confirmJob)await confirmJob();break;
    case 'profile':profileForm();break;
    case 'interests':interestsForm();break;
    case 'filters':filtersForm();break;
    case 'create':await eventForm();break;
    case 'refresh':await Promise.all([refreshPersonal(),refreshCatalogs()]);await loadView();break;
    case 'reset':clearFilters();await loadView();break;
    case 'clear-extra':state.filters={};state.page=1;await loadView();break;
    case 'my-school':if(!state.me.school_id){profileForm();toast('Сначала выбери школу в профиле');break;}state.city=String(state.me.city_id);state.school=String(state.me.school_id);state.page=1;await loadView();break;
    case 'map-world':EventMap.world();break;
    case 'map-expand':EventMap.expand();break;
    case 'map-locate':EventMap.locate();break;
    case 'picker-locate':EventMap.locate(true);break;
    case 'picker-expand':EventMap.expandPicker();break;
    case 'map-city':EventMap.city();break;
    case 'calendar-nearest':{
      const user=state.me.id,version=requestNumber,mode=state.calendarMode,current=new Date();
      const query={...filtersQuery(),sort:'date',date_from:current.toISOString(),limit:1,page:1};delete query.date_to;
      const events=mode==='mine'?(await Api.all('/me/plans',{date_from:query.date_from})).map(x=>x.event).filter(e=>matchesFilters(e,{...state.filters,date:undefined})).filter(e=>e.status!=='cancelled').sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)):(await Api.request('/events?'+Api.query(query))).items;
      if(state.me?.id!==user||state.view!=='calendar'||requestNumber!==version||state.calendarMode!==mode)return;
      if(!events.length){toast(mode==='mine'?'В планах нет предстоящих событий с выбранными фильтрами.':'Предстоящих событий с выбранными фильтрами нет.');break;}
      Object.assign(state,EventDates.calendarPosition(Math.max(current.getTime(),new Date(events[0].starts_at).getTime())));
      delete state.filters.date;await loadView();break;
    }
    case 'calendar-today':{const d=new Date();state.year=d.getFullYear();state.month=d.getMonth();state.day=EventDates.dateKey(d);await loadView();break;}
    case 'logout':await Api.logout();endSession();showAuth();history.replaceState(null,'','#feed');break;
    case 'deactivate':confirmAction('Деактивировать аккаунт?','Ты выйдешь из аккаунта и больше не сможешь войти под ним. История мероприятий сохранится.',async()=>{await Api.request('/me',{method:'DELETE'});Api.clear();endSession();showAuth('login','Аккаунт деактивирован.');});break;
  }
}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||(b.form&&b.type==='submit')||b.disabled)return;b.disabled=true;try{await handleClick(b);}catch(error){showError(error);}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;if(form.dataset.busy)return;form.dataset.busy='true';const submit=form.querySelector('[type=submit]')||form.querySelector('button:not([type])');if(submit)submit.disabled=true;const errorBox=form.querySelector('.form-error');if(errorBox)errorBox.textContent='';
  try{
    const fd=new FormData(form);const numeric=k=>fd.get(k)===''?null:Number(fd.get(k));
    if(form.id==='reminder-form'){await Reminders.submit(form);}
    else if(['team-form','team-join-form','review-form','scan-form','team-search-form'].includes(form.id)){await Activity.submit(form);}
    else if(form.id==='auth-form'){
      if(form.dataset.mode==='register'){if(fd.get('password')!==fd.get('confirm'))throw new Error('Пароли не совпадают.');await Api.request('/auth/register',{method:'POST',auth:false,body:{name:String(fd.get('name')).trim(),email:String(fd.get('email')).trim(),password:fd.get('password'),role:fd.get('role')}});form.dataset.mode='login';if(submit)submit.textContent='Войти';}
      await Api.login(String(fd.get('email')).trim(),fd.get('password'));clearFilters();await initialize();
    }else if(form.id==='profile-form'){state.me=await Api.request('/me',{method:'PATCH',body:{name:String(fd.get('name')).trim(),city_id:numeric('city_id'),...(state.me.role!=='organizer'?{grade:numeric('grade'),school_id:numeric('school_id')}:{}),...(canOrganize()?{max_contact_url:String(fd.get('max_contact_url')||'').trim()||null}:{})}});closeModal();await afterMutation();toast('Профиль сохранён');}
    else if(form.id==='interests-form'){state.interests=await Api.request('/me/interests',{method:'PUT',body:{topic_ids:fd.getAll('topic').map(Number)}});closeModal();await loadView();toast('Интересы сохранены');}
    else if(form.id==='filters-form'){const values=Object.fromEntries([...fd].filter(([,v])=>v!==''));if(values.price_min!=null&&values.price_max!=null&&Number(values.price_min)>Number(values.price_max))throw new Error('Минимальная цена больше максимальной.');if(state.view==='calendar'&&values.date){const date=new Date(values.date+'T12:00:00');state.year=date.getFullYear();state.month=date.getMonth();state.day=values.date;delete values.date;}state.filters=values;state.page=1;closeModal();await loadView();}
    else if(form.id==='event-form')await saveEvent(form);
    else if(form.id==='reject-form'){await Api.request(`/events/${form.dataset.id}/reject`,{method:'POST',body:{comment:String(fd.get('comment')).trim()}});const id=form.dataset.id;closeModal();await afterMutation();await openEvent(id);}
    else if(form.id==='catalog-form'){const body=Object.fromEntries(fd);for(const key of ['city_id','latitude','longitude'])if(key in body)body[key]=numeric(key);const kind=form.dataset.kind,id=form.dataset.id;await Api.request('/'+kind+(id?'/'+id:''),{method:id?'PATCH':'POST',body});await refreshCatalogs();closeModal();await loadView();toast('Справочник обновлён');}
  }catch(error){if(form.id==='auth-form'&&error.status===401){if(errorBox)errorBox.textContent=error.message;}else showError(error,form);}finally{delete form.dataset.busy;if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('change',async event=>{const el=event.target;try{
  if(el.id==='scan-photo'){await Activity.photo(el.files[0]);return;}
  if(el.id==='challenge-month'||el.id==='challenge-history'){if(el.value){state.challengeMonth=el.value;await loadView();}return;}
  if(el.id==='geo-city'){state.city=el.value;state.school='';state.page=1;EventMap.invalidateCity();await loadView();}
  if(el.id==='geo-school'){state.school=el.value;state.page=1;await loadView();}
  if(el.id==='sort'){state.sort=el.value;state.page=1;await loadView();}
  if(el.id==='manage-status'){state.status=el.value;state.page=1;await loadView();}
  if(el.hasAttribute('data-form-city')){if(el.form.elements.school_id)el.form.elements.school_id.innerHTML=schoolOptions(el.value,'','Без школы');EventMap.pickerCity(el.value);}
  if(el.hasAttribute('data-form-school')&&el.form.id==='event-form'){const school=state.schools.find(s=>s.id===Number(el.value));if(school)EventMap.applySchool(school);}
  if(el.hasAttribute('data-format')||el.hasAttribute('data-registration-mode'))updateEditorFields();
  if(el.hasAttribute('data-coordinate'))EventMap.pickerCoordinates();
}catch(error){showError(error);}});
$('#search').addEventListener('input',e=>{state.search=e.target.value;state.page=1;clearTimeout(searchTimer);searchTimer=setTimeout(loadView,300);});
document.querySelectorAll('.brand,.mobile-brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();if(state.me)navigate('feed');}));
window.addEventListener('popstate',()=>{if(state.me){state.view=location.hash.slice(1)||'feed';if(!['feed','map','saved','calendar','registrations','manage','admin','achievements','leaderboard','passport','teams','challenges','schoolboard','reminders'].includes(state.view)||state.view==='manage'&&!canOrganize()||state.view==='admin'&&state.me.role!=='admin')state.view='feed';state.page=1;loadView();}});
$('#modal').addEventListener('cancel',()=>{window.Activity?.stop();detailNumber++;EventMap.closePicker();modalKind='';});
document.addEventListener('keydown',e=>{if(e.key==='/'&&state.me&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}});
fillIcons();
if(Api.hasSession())initialize().catch(error=>{if(error.status!==401)showAuth('login',error.message);});else showAuth();
